//! Function-level differential fixtures generated by the pinned legacy source.
//! This does not claim two-CLI end-to-end equivalence.
use pi_agent::AgentOptions;
use pi_core::{AgentEvent, ToolResult};
use pi_rpc::json_wire::session_event_json;
use pi_runtime::PiRuntime;
use pi_session::{AgentSession, AgentSessionEvent, AgentSessionOptions};
use pi_test_support::ScriptedProviderPlugin;
use serde_json::Value;

#[tokio::test]
async fn tool_event_results_preserve_legacy_structured_content() {
    let directory = tempfile::tempdir().unwrap();
    let runtime = PiRuntime::builder()
        .provider_plugin(ScriptedProviderPlugin::scripted([]))
        .agent_options(AgentOptions {
            cwd: directory.path().to_path_buf(),
            provider_id: "scripted".into(),
            model_id: "test".into(),
            ..AgentOptions::default()
        })
        .build()
        .unwrap();
    let mut options = AgentSessionOptions::default();
    options.in_memory = true;
    let session = AgentSession::create(runtime, directory.path().join("session.jsonl"), options)
        .await
        .unwrap();
    let corpus: Value =
        serde_json::from_str(include_str!("fixtures/rpc-tool-events.json")).unwrap();
    for case in corpus["cases"].as_array().unwrap() {
        let input = &case["input"];
        let update = input["type"] == "tool_execution_update";
        let wire_result = &input[if update { "partialResult" } else { "result" }];
        let mut result = ToolResult::text("visible");
        result.content = serde_json::from_value(wire_result["content"].clone()).unwrap();
        result.structured_content = wire_result.get("structuredContent").cloned();
        result.details = wire_result.get("details").cloned();
        let tool_call_id = input["toolCallId"].as_str().unwrap().into();
        let tool_name = input["toolName"].as_str().unwrap().to_string();
        let event = if update {
            AgentEvent::ToolExecutionUpdate {
                tool_call_id,
                tool_name,
                args: input["args"].clone(),
                partial_result: result,
            }
        } else {
            AgentEvent::ToolExecutionEnd {
                duration_ms: input.get("durationMs").and_then(Value::as_u64),
                tool_call_id,
                tool_name,
                result,
                is_error: false,
            }
        };
        assert_eq!(
            session_event_json(AgentSessionEvent::Agent(Box::new(event)), &session)
                .unwrap()
                .unwrap(),
            case["expected"],
            "legacy input: {input}",
        );
    }
}
